    expect(await ui.claimAction(pg_uma, c_uma_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_uma_1, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
